def can_finish(num_courses, prerequisites):
    incoming = [0] * num_courses
    unlocks = {}
    for course, prereq in prerequisites:
        incoming[course] += 1
        unlocks.setdefault(prereq, []).append(course)
    ready = [c for c in range(num_courses) if incoming[c] == 0]
    taken = 0
    while ready:
        course = ready.pop()
        taken += 1
        for nxt in unlocks.get(course, []):
            incoming[nxt] -= 1
            if incoming[nxt] == 0:
                ready.append(nxt)
    return taken == num_courses

bruteForceCode:
def can_finish(num_courses, prerequisites):
    unlocks = {}
    for course, prereq in prerequisites:
        unlocks.setdefault(prereq, []).append(course)
    for start in range(num_courses):
        seen = set()
        stack = [start]
        while stack:
            course = stack.pop()
            if course in seen:
                continue
            seen.add(course)
            for nxt in unlocks.get(course, []):
                if nxt == start:
                    return False
                stack.append(nxt)
    return True
